+static bool osd_keepalive_timed_out(struct ceph_osd *osd)
+{
+	if (!time_after_eq(jiffies,
+			   osd->o_keepalive_stamp + CEPH_OSD_PING_TIMEOUT))
+		return false;
+
+	return ceph_con_keepalive_expired(&osd->o_con, CEPH_OSD_PING_TIMEOUT);
+}
